def components(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=set()
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((col,cells))
    return bg,out

def transform(grid):
    # Find the two largest same-shape foreground components (colors may differ).
    bg, objs = components(grid)
    shapes=[]
    for color,cells in objs:
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        shape=frozenset((r-r0,c-c0) for r,c in cells)
        shapes.append((color,cells,shape))
    matches=[]
    for i,a in enumerate(shapes):
        for b in shapes[i+1:]:
            if a[2]==b[2] and a[0]!=b[0]:
                matches.append((len(a[1]),a,b))
    if not matches: return [row[:] for row in grid]
    _,a,b=max(matches,key=lambda x:x[0])
    # Keep the more prominent occurrence intact; recolor the smaller/later one
    # to the separator color if a monochrome separator exists, else other copy's color.
    # For this stream, the horizontally/vertically continuous rail provides target color.
    bars=[]
    h,w=len(grid),len(grid[0])
    for color,cells in objs:
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        if len(cells)>=3 and (len(set(rs))==1 or len(set(cs))==1): bars.append((len(cells),color))
    newcolor=max(bars)[1] if bars else a[0]
    # recolor the second matched component (copy associated with separate shape)
    target=b[1]
    out=[row[:] for row in grid]
    for r,c in target: out[r][c]=newcolor
    return out
