 "content": "from collections import Counter, deque

def transform(grid):
    """Color the lower occurrence of a repeated component with the guide color."""
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); objects=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=set()
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objects.append((color,cells))
    def canon(cells):
        pts=list(cells); forms=[]
        for k in range(8):
            tr=[]
            for r,c in pts:
                if k==0:y,x=r,c
                elif k==1:y,x=r,-c
                elif k==2:y,x=-r,c
                elif k==3:y,x=-r,-c
                elif k==4:y,x=c,r
                elif k==5:y,x=c,-r
                elif k==6:y,x=-c,r
                else:y,x=-c,-r
                tr.append((y,x))
            a=min(y for y,x in tr); b=min(x for y,x in tr)
            forms.append(tuple(sorted((y-a,x-b) for y,x in tr)))
        return min(forms)
    groups={}
    for col,cells in objects: groups.setdefault(canon(cells),[]).append((col,cells))
    candidates=[]
    for shape,group in groups.items():
        if len(group)>1 and len({col for col,cells in group})>1:
            candidates.append((len(shape),group))
    if not candidates:return [row[:] for row in grid]
    _,group=max(candidates,key=lambda p:p[0])
    target=max(group,key=lambda o:max(r for r,c in o[1]))
    # Guide color is the most prominent straight/L separator component.
    bars=[]
    for col,cells in objects:
        rows=Counter(r for r,c in cells); cols=Counter(c for r,c in cells)
        if max(rows.values(),default=0)>=4 and max(cols.values(),default=0)>=4:
            bars.append((len(cells),col))
    guide=max(bars)[1] if bars else bg
    out=[row[:] for row in grid]
    for r,c in target[1]:out[r][c]=guide
    return out

