            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            components.append((color, cells))

    # The long colored L/bar is the guide color; its bounding box is much
    # larger than the small disconnected motif components.
    guide_candidates = []
    for color, cells in components:
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        if len(cells) >= 5 and len(set(rs)) >= 3 and len(set(cs)) >= 3:
            guide_candidates.append((len(cells), color))
    if not guide_candidates:
        return [row[:] for row in grid]
    guide_color = max(guide_candidates)[1]

    # Recolor the detached, straight marker-like component (a line/short bar)
    # to the guide color. Exclude the big guide and other repeated pattern fields.
    candidates = []
    for color, cells in components:
        if color == guide_color or len(cells) < 2:
            continue
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        if len(set(rs)) == 1 or len(set(cs)) == 1:
            candidates.append((len(cells), min(rs), min(cs), cells))
    if not candidates:
        return [row[:] for row in grid]
    # Select lowest such straight component, a stable marker position relative
    # to the decorative motifs in this task family.
    _, _, _, target = max(candidates, key=lambda x: (x[1], x[0], x[2]))
    out = [row[:] for row in grid]
    for r,c in target:
        out[r][c] = guide_color
    return out

